-- Mod-authored great work descriptions, ko_KR overlay.
-- Baseline in CivVAccess_GreatWorkDescStrings_en_US.lua.
CivVAccess_Strings = CivVAccess_Strings or {}

CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_MISSING"] =
    "이 위대한 작품에 대한 그림 설명이 없습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_GIRL_WITH_PEARL_EARRING"] =
    "네덜란드 황금기의 유화로, 서양 미술에서 가장 사랑받는 초상화 중 하나입니다. 젊은 여자가 어깨 너머로 고개를 돌려 단순한 어두운 배경 속에서 보는 이와 눈을 맞추고 있으며, 입술은 막 말을 꺼내려는 듯 살짝 벌어져 있습니다. 그녀는 파란색과 금색의 터번을 두르고 있는데, 그 천이 등 뒤로 흘러내리며, 귀에는 커다란 물방울 모양 진주 하나가 빛을 받고 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_HENRY_VIII"] =
    "튜더 궁정의 유화 초상화로, 세상이 헨리 8세를 떠올리는 모습을 고정시킨 그림입니다. 왕은 정면을 향해 전신으로 서 있으며, 두 발을 넓게 벌리고, 어깨가 넓고 육중한 몸으로, 한 손은 허리에 찬 단검 위에 얹고 있습니다. 그는 모피로 안을 댄 진홍색 코트 안에 보석으로 장식된 은색 더블릿을 받쳐 입고, 평평한 깃털 모자를 쓰고, 금 사슬을 두른 채, 대리석 기둥 사이 문양이 들어간 카펫 위에 서 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_HUNTERS_IN_THE_SNOW"] =
    "플랑드르 르네상스의 유화로, 언덕 꼭대기에서 내려다본 겨울 풍경입니다. 지친 사냥꾼 셋과 그들의 사냥개 무리가 전경에서 고개를 숙인 채 깊은 눈 속을 터벅터벅 걸으며, 사냥의 성과라고는 여우 한 마리뿐입니다. 그들 아래로 회록색 하늘 아래 마을이 펼쳐져 있으며, 얼어붙은 연못 위에서 작은 스케이터들이 놀고 있고, 저 멀리 들쭉날쭉한 봉우리들이 솟아 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_LES_DEMOISELLES"] =
    "초기 모더니즘의 유화로, 입체파를 탄생시킨 작품입니다. 다섯 명의 나체 여인이 들쭉날쭉한 분홍색, 흰색, 파란색 면으로 이루어진 얕은 공간에 서거나 앉아 있으며, 그들의 몸은 날카롭고 각진 형태로 분해되어 있습니다. 오른쪽의 두 얼굴은 줄무늬와 일그러진 형상으로 아프리카 가면처럼 그려져 있고, 나머지는 크고 아몬드 모양의 눈으로 정면을 응시하고 있으며, 아래쪽 가장자리에는 작은 과일 그릇 하나가 놓여 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_LUNCHEON"] =
    "식사를 마친 뒤 머무는 친구들을 그린 프랑스 인상주의 유화입니다. 여름옷을 입은 활기찬 무리가 주황색과 흰색 줄무늬 차양 아래 강가의 발코니에 빽빽이 모여 이야기하고, 시시덕거리고, 난간에 기대어 있으며, 앞쪽의 젊은 여자 하나는 작은 개와 놀고 있습니다. 탁자에는 포도주병과 잔과 과일이 어지러이 놓여 있으며, 모두 햇빛에 물든 따뜻하고 느슨한 붓 터치로 그려져 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_MONA_LISA"] =
    "이탈리아 르네상스의 목판 유화로, 아마도 세계에서 가장 유명한 초상화일 것입니다. 한 여인이 두 손을 포갠 채 앉아 보는 이를 향해 약간 몸을 돌리고 있으며, 그 뒤로는 굽이치는 강과 멀리 푸른 산이 펼쳐진 안개 낀 풍경이 자리합니다. 그녀의 눈은 보는 이를 똑바로 마주하는데, 어디에 서 있든 따라오는 듯한 그 유명한 시선입니다. 그녀의 희미한 엷은 미소가 그림의 초점으로, 부드러운 갈색과 초록색으로 또렷한 윤곽선 없이 그려져 오래 바라볼수록 그 표정이 변하는 듯합니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_SUNDAY_AFTERNOON"] =
    "점묘법으로 그린 유화로, 전체가 순색의 작은 점들로만 이루어져 있습니다. 가장 좋은 나들이옷을 차려입은 파리 사람들이 햇살 가득한 강가의 잔디밭에서 쉬며, 파라솔을 들고 거닐거나, 풀밭에 누워 있거나, 작은 개를 데리고 산책하고 있으며, 그들 뒤 물 위에는 돛단배들이 떠 있습니다. 모두가 프리즈 속 인물들처럼 묘하게 정지해 있고 격식을 차린 모습이며, 빛은 초록색, 주황색, 보라색 알갱이들의 어른거림으로 분해되어 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_VIEW_OF_TOLEDO"] =
    "스페인 르네상스의 유화로, 서양 미술에서 가장 이른 순수 풍경화 중 하나이자 유난히 어두운 작품입니다. 스페인의 언덕 도시 톨레도가 사나운 폭풍 하늘 아래 저 멀리 솟아 있으며, 회색 첨탑과 성벽이 으스스한 은빛으로 빛나고 있습니다. 초록 언덕이 전경의 강으로 굽이쳐 내려가고, 장면 전체는 한낮보다 꿈에 가깝게 느껴지는 짙은 초록색과 청흑색으로 그려져 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_WATER_LILIES"] =
    "지베르니에 있는 자신의 정원 연못을 그린 모네의 유명한 연작 중 한 점인 프랑스 인상주의 유화입니다. 화면 전체가 물의 표면으로, 수평선도 물가도 없습니다. 초록 수련 잎 무리가 분홍색과 붉은색 꽃이 점점이 박힌 파란색과 라벤더색 물 위로 떠다닙니다. 구름과 나무는 부드러운 반영으로만 나타나며, 붓질이 충분히 느슨하여 모든 것이 떠 있는 듯합니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_STARRY_NIGHT"] =
    "후기 인상주의 유화로, 현대 미술에서 가장 널리 알려진 그림 중 하나입니다. 화면 대부분을 움직임으로 살아 있는 밤하늘이 가득 채우고 있습니다. 별들이 소용돌이치는 후광 속에서 타오르고, 달은 한쪽 구석에서 주황빛으로 불타며, 거대한 나선형 물결이 하늘 한가운데를 가로질러 굽이칩니다. 그 아래로 뾰족한 교회 첨탑이 있는 고요한 마을이 언덕 사이에서 잠들어 있고, 어두운 사이프러스 나무 한 그루가 왼쪽 가장자리에서 불꽃처럼 솟아오르며, 모두 파란색과 금색의 두껍고 또렷한 붓 터치로 그려져 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_BIRTH_OF_VENUS"] =
    "바다에서 도착하는 사랑의 여신을 그린 이탈리아 르네상스 그림으로, 고전 신화를 다룬 가장 유명한 이미지 중 하나입니다. 비너스는 거대한 가리비 껍데기 위에 나체로 서서 두 손과 길게 흘러내린 금빛 머리카락으로 몸을 가리고 있습니다. 왼쪽에서는 날개 달린 두 바람의 신이 분홍 장미 비를 뿌리며 그녀를 물가로 불어 보내고, 오른쪽에서는 꽃무늬 드레스를 입은 여인이 휘날리는 망토로 그녀를 감싸려 달려옵니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_BINDO_ALTOVITI"] =
    "부유한 젊은 로마 은행가를 그린 이탈리아 전성기 르네상스의 유화 초상입니다. 길고 금빛 도는 머리카락에 검은 모자를 쓴 잘생긴 젊은 남자가 드러난 어깨 너머로 보는 이를 돌아보며, 한 손을 가슴으로 가져가고 있습니다. 그는 검은 옷 위에 파란 망토를 걸치고 있으며, 그의 창백한 얼굴이 짙은 초록색 배경에 환하게 빛납니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_SAINT_GEORGE_DRAGON"] =
    "동화처럼 뻣뻣하면서도 그림책 같은 매력을 지닌 초기 이탈리아 르네상스 그림입니다. 오른쪽에서는 갑옷을 입은 기사가 앞발을 든 백마 위에서 창을 들어 점박이 나방 같은 날개를 가진 날개 달린 초록 용의 벌린 아가리에 찔러 넣고 있습니다. 왼쪽에서는 긴 분홍 가운을 입은 차분한 공주가 어두운 동굴 앞에서 상처 입은 짐승을 애완동물처럼 끈으로 붙잡고 있으며, 기사 뒤로는 기이한 나선형 폭풍이 모여들고 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_CREATION_OF_ADAM"] =
    "시스티나 성당 천장에 그려진 이탈리아 르네상스 프레스코로, 미술에서 가장 유명한 동작 중 하나의 원천입니다. 나체의 아담이 왼쪽 초록 언덕에 비스듬히 기대어 한 팔을 힘없이 뻗고 있으며, 천사들로 가득한 휘날리는 장미색 수의를 두른 회색 수염의 신이 오른쪽에서 밀려 들어옵니다. 두 사람의 뻗은 검지가 작은 틈을 사이에 두고 서로를 향해 다가가는데, 생명의 불꽃이 튀기 직전의 순간입니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_GALLERY_OF_THE_LOUVRE"] =
    "루브르 박물관 내부의 한 전시실을 그린 미국 유화로, 훗날 전신 부호를 발명한 바로 그 모스가 그렸습니다. 붉은 벽으로 둘러싸인 웅장한 살롱은 바닥부터 천장까지 금박 액자에 담긴 수십 점의 옛 거장 그림으로 빽빽이 덮여 있으며, 그중에는 자그마한 모나리자도 있습니다. 전경에서는 미술 학생들이 이젤 앞에 앉아 모사를 하고 있고, 그들의 스승은 한 젊은 여인의 어깨 너머로 몸을 숙여 그녀의 작업을 바로잡아 주고 있으며, 저 멀리 다른 전시실들로 이어지는 아치형 회랑이 열려 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_WASHINGTON_CROSSING"] =
    "영웅적인 미국 역사화 유화로, 독립 전쟁의 상징이 된 작품입니다. 워싱턴 장군은 사람들로 가득 찬 노 젓는 배의 뱃머리에 꼿꼿이 서 있고, 그의 병사들은 얼음 덩어리로 막힌 강을 삿대질하고 노 저으며 헤쳐 나가고 있으며, 그 뒤의 한 장교는 미국 국기를 높이 들고 있습니다. 차가운 안개를 뚫고 새벽빛이 비쳐 들고, 사람과 말을 가득 실은 다른 배들이 그 뒤를 따르고 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_ARRANGEMENT_IN_GREY"] =
    "흔히 휘슬러의 어머니로 알려진 미국 유화입니다. 긴 검은 드레스에 흰 레이스 모자를 쓴 노년의 여인이 정확한 옆모습으로 왼쪽을 향해 앉아 있으며, 두 손은 무릎 위에 포개고 두 발은 작은 발받침 위에 올려 두었습니다. 방은 엄숙하고 평면적입니다. 회색 벽, 어두운 무늬의 커튼, 그리고 액자에 담긴 그림 한 점이 있을 뿐으로, 전체 구도는 제목 그대로 회색과 검은색의 습작처럼 균형을 이루고 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_BREEZING_UP"] =
    "뉴잉글랜드 해안에서의 작은 배 항해를 그린 미국 사실주의 유화입니다. 한 남자와 세 소년이 거센 바람 속에서 한쪽으로 기울어진 글로스터라는 이름의 작은 캣보트에 몸을 뒤로 젖히고 있으며, 뱃머리에서는 물보라가 부서지고 발치에는 그날 잡은 물고기가 쌓여 있습니다. 바다는 흩어진 구름 아래 거칠게 일렁이는 초록빛이며, 수평선에는 쌍돛대 스쿠너 한 척이 떠 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_A_THOUSAND_LI"] =
    "송나라 궁정의 십 대 천재가 비단 위에 그린 청록 산수 두루마리이며 길이가 거의 십이 미터에 이릅니다. 선명한 광물질 청록색의 산들이 잔잔한 금빛 강 위로 능선에 능선을 거듭하며 솟아 있고, 비탈 사이사이에는 자그마한 마을과 다리, 헐벗은 나무들이 자리 잡고 있습니다. 봉우리 위 하늘에는 붓으로 쓴 글씨의 행들과 붉은 수장인이 가득합니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_DWELLING_IN_THE_FUCHUN"] =
    "종이 위에 오로지 검은 먹의 농담만으로 그린 원나라 문인 산수화의 걸작 수묵 두루마리입니다. 마르고 겹겹이 쌓인 붓질로 빚어낸 둥근 산들이 넓고 잔잔한 강 위로 솟아 있고, 강기슭을 따라 소나무와 드문드문한 초가, 고깃배들이 자리하고 있습니다. 분위기는 여유롭고 사색적이며, 종이에는 수백 년에 걸쳐 감상자들이 남긴 붉은 수장인이 점점이 찍혀 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_ALONG_THE_RIVER"] =
    "비단 위에 그린 송나라 두루마리로, 길이가 오 미터가 넘는, 도시 일상의 유명한 파노라마입니다. 보이는 부분은 수도의 거대한 성문을 중심으로 삼고 있는데, 경사진 성벽 위에 육중한 목조 누각이 솟아 있고, 그 아래 거리는 생기로 넘쳐납니다. 노점과 소달구지, 성문을 지나는 낙타 대상, 어깨에 멜대로 짐을 진 짐꾼들이 보입니다. 모든 인물은 자그마하지만 가는 먹선으로 정밀하게 그려졌으며 차분한 흙빛 색조를 띱니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_LEAF_2"] =
    "가는 선과 섬세한 색채로 그린 청나라 궁정 화첩의 한 장입니다. 흰색, 녹색, 파란색의 길고 하늘거리는 로브를 입은 우아한 여인들이 밝은 파란 천이 드리워진 정원 정자에 모여 있으며, 그중 한 명은 붉은 난간 뒤 탁자에서 향을 피우고 있습니다. 그들 주위에는 정원석과 대나무가 있고, 꽃이 핀 덩굴이 정자 지붕 위로 타고 올라가 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_EMPEROR_TAIZONG"] =
    "비단 위에 그린 당나라 두루마리로, 외교 회견을 기록한 궁정화입니다. 오른쪽에는 궁녀들이 떠받친 단 위에 태종이 앉아 있고, 궁녀들은 커다란 부채 두 개와 붉은 일산을 그의 머리 위로 들고 있습니다. 왼쪽에는 더 작게 그려진 세 인물이 공손한 자세로 다가옵니다. 붉은 옷을 입은 궁정 의전관, 무늬가 있는 로브를 걸친 티벳 사절, 그리고 흰옷을 입은 통역관이며, 이들 모두 붉은 인장이 가득 찍힌 따뜻한 금빛 비단을 배경으로 하고 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_SPRING_MORNING"] =
    "비단 위에 그린 명나라 두루마리로, 봄날 아침 한가로이 지내는 궁중 여인들을 담은 긴 파노라마입니다. 수십 명의 우아한 여인들이 트인 전각과 회랑, 안뜰을 가득 메우고 있습니다. 음악을 연주하고, 초상을 그리고, 아이들과 놀고, 버드나무와 정원석, 심지어 공작 사이를 거닐고 있습니다. 궁전 건축물이 따뜻한 붉은색과 녹색으로 두루마리 전체에 걸쳐 이어지며, 모든 가림막과 난간과 로브가 정교한 가는 선으로 세밀하게 묘사되어 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_THE_GREAT_WAVE"] =
    "일본 우키요에 목판화로, 일본 미술에서 가장 유명한 단 하나의 이미지입니다. 짙은 파란색의 거대한 파도가 왼쪽에서 솟구쳐 올라 화면 전체를 뒤덮으며 굽이치고, 그 마루는 갈고리 같은 흰 거품의 손가락들로 부서집니다. 그 아래에서는 노 젓는 사람들로 가득한 길고 트인 배 세 척이 물결의 골을 타고 있으며, 저 멀리 그 모든 것의 한가운데에 작게, 눈 덮인 후지산의 원뿔이 자리하고 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_EVENING_SHOWER"] =
    "일본 우키요에 목판화로, 지금껏 만들어진 빗속 풍경 중 가장 사랑받는 작품의 하나입니다. 가늘게 비스듬히 그은 선의 장막으로 표현된 갑작스러운 소나기가 긴 목조 다리를 절반쯤 건너던 사람들을 덮치고, 그들은 삿갓과 우산을 쓴 채 양방향으로 서두르며, 그중 한 명은 거적 아래 몸을 피하고 있습니다. 아래의 강은 청록색 띠를 이루고 외로운 뗏목꾼 한 명이 삿대질하며 지나가고 있으며, 건너편 기슭은 폭풍 아래 어두운 얼룩으로 흐려져 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_L_ABSINTHE"] =
    "파리 카페 생활의 가차 없는 장면을 담은 프랑스 인상주의 유화입니다. 연한 드레스에 모자를 쓴 여인이 대리석 카페 탁자 앞에 축 늘어진 채 시선을 떨구고 앉아 있으며, 그녀 앞에는 뿌연 초록빛 압생트 한 잔이 놓여 있습니다. 그 곁에는 구겨진 코트를 입은 수염 난 남자가 입에 파이프를 문 채 오른쪽 먼 곳을 응시하고 있습니다. 두 사람은 함께 앉아 있으면서도 완전히 동떨어져 있으며, 이 그림의 고독한 분위기를 자아내는 칙칙한 회색과 갈색으로 그려졌습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_UPAUPA_SCHNEKLUD"] =
    "연주 중인 첼리스트를 그린 후기 인상주의 유화 초상입니다. 음악가는 선명한 주황빛 도는 붉은 첼로 위로 몸을 숙이고 집중한 듯 눈을 내리깐 채 활을 든 팔로 현을 가로지르며 켜고 있으며, 그의 짙은 파란 정장이 빛나는 악기를 감싸듯 둘러싸고 있습니다. 그의 뒤로 배경은 갈색과 이끼 낀 녹색의 평면적인 구역으로 나뉘어 연한 추상적 형상들이 흩어져 있으며, 고갱 특유의 대담하고 단순화된 색채 양식으로 그려졌습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_A_BAR_AT_THE_FOLIES"] =
    "마네의 마지막 대작인 프랑스 근대 생활을 그린 유화입니다. 검은 벨벳 보디스에 가슴께 꽃을 단 여급이 샴페인 병들과 오렌지가 담긴 그릇, 장미가 꽂힌 잔으로 가득한 대리석 카운터 뒤에 서서 지치고 아득한 표정으로 정면을 바라봅니다. 그녀의 뒤에는 거대한 거울이 샹들리에와 군중으로 반짝이는 뮤직홀을 비추고 있으며, 오른쪽으로 묘하게 어긋난 자리에는 실크해트를 쓴 한 남자에게 몸을 기울인 그녀 자신의 뒷모습이 비쳐 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_BALL_AT_THE_MOULIN"] =
    "유명한 카바레의 파리 밤 풍경을 그린 후기 인상주의 유화입니다. 실크해트를 쓴 남자들과 깃털 모자를 쓴 여자들이 술잔을 놓은 탁자에 둘러앉아 있고, 그들 뒤로 초록빛으로 물든 무도장에서는 붉은 머리의 여자가 머리를 매만지고 있습니다. 오른쪽 가장자리에는 한 여자의 얼굴이 아래에서 비추는 빛에 유령처럼 초록빛으로 떠올라 있으며, 로트레크 특유의 포스터 같은 화풍으로 긴 대각선 난간이 전경을 가로지릅니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_THE_KISS"] =
    "클림트의 가장 유명한 작품으로, 진짜 금박을 겹겹이 입힌 빈 아르누보 유화입니다. 키스는 꽃이 핀 풀밭 위에서 한 쌍의 연인이 무릎을 꿇은 채 서로를 끌어안고 있는 그림으로, 남자가 몸을 숙여 여자의 뺨에 입을 맞추고 여자는 눈을 감은 채 얼굴을 위로 들어 올리고 있습니다. 두 사람의 몸은 하나의 금빛 망토로 녹아드는데, 남자 쪽은 직사각형 문양으로, 여자 쪽은 밝은 원형 문양으로 채워져 있으며, 평면적으로 일렁이는 금빛 배경을 등지고 빛나고 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_AMERICAN_GOTHIC"] =
    "끝없이 패러디되어 한눈에 알아볼 수 있는 미국 지방주의 유화입니다. 미국 고딕은 둥근 안경을 쓰고 데님 멜빵바지를 입은 머리가 벗어진 엄격한 표정의 농부가 세 갈래 쇠스랑을 곧게 세워 들고 서 있는 그림으로, 그 곁에는 어두운 무늬의 앞치마 드레스를 입은 여자가 입술을 앙다문 못마땅한 표정으로 옆을 바라보고 있습니다. 그들 뒤에는 그림의 이름이 된 흰 농가가 있으며, 박공에는 뾰족한 아치형 고딕 창문이 나 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_SRI_SHANMUKAHA"] =
    "라비 바르마가 인도 전역에 널리 알린 유럽 아카데미 양식으로 그려진 인도 종교화입니다. 스리 산무카하 서브라마니아 스와미는 힌두교 신 무루간이 왕관을 쓴 여섯 개의 머리와 무기를 든 여러 개의 팔로 자신의 탈것인 공작을 타고 있는 그림으로, 양옆에는 선명한 분홍색 사리를 입은 두 배우자가 서 있습니다. 공작의 꼬리는 그들 뒤로 초록색과 금색 눈 문양이 박힌 거대한 부채처럼 펼쳐져 있으며, 새는 발아래 코브라 한 마리를 짓누르고 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_DAUD_RECEIVES_A_ROBE"] =
    "삽화가 든 황실 연대기에서 가져온 무굴 세밀화로, 종이에 불투명 수채와 금으로 그려졌습니다. 무님 칸에게서 명예로운 카프탄을 받는 다우드에서 화면에 보이는 부분은 연한 로브에 붉은 모자, 금빛 띠를 두른 호리호리한 젊은 시종을 중심으로 하며, 그는 수여식을 위해 접힌 금빛 명예의 로브를 들고 있습니다. 그는 섬세한 꽃넝쿨로 뒤덮인 선명한 파란색 천막 벽을 등지고 서 있으며, 모든 주름과 꽃송이가 세밀화 특유의 정밀함으로 그려져 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_YUSEF_AND_ZULEYKHA"] =
    "삽화가 든 사본에서 가져온 페르시아 세밀화로, 헤라트의 거장 베흐자드의 가장 유명한 작품입니다. 유세프와 줄레이카는 평면화된 단면으로 그려진 정교한 궁전이 화면을 가득 채우는데, 파랑, 주황, 금색 타일로 장식된 계단과 발코니, 출입구가 미로처럼 얽혀 있습니다. 위층의 한 방에서는 불꽃 같은 후광에 둘러싸인 예언자 유세프가 줄레이카의 뻗은 손길을 피해 달아나고 있으며, 페르시아 서예가 적힌 패널들이 건축물을 틀로 감싸고 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_THE_ASCENT_OF_MUHAMMAD"] =
    "왕실 사본에서 가져온 페르시아 세밀화로, 예언자가 하늘을 가로질러 떠난 밤의 여정을 그리고 있습니다. 승천하는 무함마드는 흰 천으로 얼굴을 가리고 금빛 불꽃에 둘러싸인 무함마드가 깊은 파란색 하늘을 가로질러 사람 머리를 한 영물 부라크를 타고 있는 그림으로, 하늘에는 금빛 가장자리의 굽이치는 구름이 흩어져 있습니다. 붉은색과 초록색, 주황색 로브를 입은 천사들이 선물과 향로를 들고 사방에서 그를 에워싸고 소용돌이치며, 페르시아 시구가 장면을 틀로 감싸고 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_LIBERTY_LEADING_THE_PEOPLE"] =
    "혁명을 상징하는 대표적인 이미지가 된 프랑스 낭만주의 유화입니다. 민중을 이끄는 자유의 여신은 자유의 여신이 직접 노란 드레스에 붉은 모자를 쓰고 가슴을 드러낸 채, 잔해와 쓰러진 시신들로 쌓인 바리케이드를 넘어 연기 자욱한 하늘로 프랑스 삼색기를 치켜드는 그림입니다. 그녀 주위로는 온갖 계층의 무장한 시민들이 밀려드는데, 그중에는 머스킷을 든 실크해트 차림의 신사와 두 자루 권총을 휘두르는 소년도 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_SAINT_JEROME_IN_HIS_STUDY"] =
    "놀라울 만큼 세밀하고 정밀하게 그려진 초기 르네상스 유화입니다. 서재에 있는 히에로니무스는 웅장한 돌 아치 너머로 보이는 장면으로, 붉은 로브를 입은 성 히에로니무스가 둥근 천장의 성당 공간 안에 무대처럼 짜인 목재 서재에 앉아 책을 읽고 있으며, 주위에는 책과 항아리가 놓인 선반들이 둘러서 있습니다. 빛은 사방의 창문에서 쏟아져 들어오고, 공작 한 마리와 자고새 한 마리가 앞쪽 문턱에 앉아 있으며, 그의 사자는 오른쪽 그림자 속을 서성이고 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_PARTHENON_FRIEZE"] =
    "고대 아테네를 상상하여 그린 빅토리아 시대 유화로, 게임에서는 파르테논 신전 불가사의와 함께 등장합니다. 파르테논 벽장식은 조각가 페이디아스가 막 채색을 마친 기마행렬 대리석 프리즈 옆 목재 비계 위에 서서, 작업장 시절의 색채가 아직 남아 있는 작품을 밧줄을 당겨 가리며 선보이는 그림입니다. 페리클레스를 비롯해 휘장 두른 로브를 입은 아테네인 한 무리가 신전 안의 따뜻한 빛 아래에서 조각을 감상하려 몸을 기울이고 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_RUE_DE_PARIS"] =
    "보슬비 내리는 날의 근대 파리를 그린 프랑스 사실주의 유화로, 인상주의 동료들의 느슨한 화풍과 달리 사진처럼 또렷합니다. 비 오는 날의 파리 길거리는 잘 차려입은 한 쌍의 남녀가 우산을 함께 쓰고 번들거리는 자갈길을 가로질러 보는 이를 향해 걸어오는 그림으로, 남자는 실크해트를 쓰고 여자는 긴 어두운 드레스를 입었으며 귀걸이가 빛을 받아 반짝입니다. 그들 주위로는 우산을 든 다른 보행자들이 넓은 교차로를 건너고 있으며, 쐐기 모양의 회색 아파트 건물들이 길을 따라 늘어서 있고, 초록색 가로등 기둥 하나가 화면 한가운데를 가르고 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_NIGHT_WATCH"] =
    "거대한 규모로 그려진 네덜란드 황금기 유화로, 지금까지 만들어진 가장 유명한 집단 초상화입니다. 야경은 도시 민병대 중대가 짙은 그림자에서 움직임을 터뜨리며 쏟아져 나오는 그림으로, 붉은 띠를 두른 검은 옷의 대장이 앞으로 성큼 나서며 연한 금색 옷을 입은 부관에게 명령을 내리는 한편, 그들 뒤로는 머스킷이 장전되고 깃발이 올라가며 한 고수가 북을 두드리고 있습니다. 빛나는 금빛 드레스를 입은 작은 소녀가 군중 속에서 신비롭게 빛나며, 어둠 속에서 스포트라이트를 받은 듯합니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_DEATH_OF_MARAT"] =
    '프랑스 혁명의 위대한 순교자 이미지가 된 프랑스 신고전주의 유화입니다. 마라의 죽음은 혁명 언론인 마라가 욕조 안에서 쓰러진 성인처럼 늘어진 채 죽어 있는 그림으로, 머리에는 흰 터번을 두르고 한쪽 팔은 여전히 깃펜을 쥔 채 바닥까지 늘어뜨리고 있습니다. 다른 한 손에는 그를 살해한 자가 안으로 들어오기 위해 이용한 편지가 들려 있고, 화폭의 위쪽 절반은 텅 빈 어두운 벽이며, 곁에 놓인 수수한 나무 상자에는 "A Marat, David."라는 헌사가 그려져 있습니다.'
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_ETIENNE_CHEVALIER"] =
    "프랑스 중세 후기의 패널화로, 유명한 신앙용 두 폭 제단화의 한쪽 날개입니다. 왕실 재무관 에티엔느 슈발리에가 화려한 붉은 로브를 입고 두 손을 모은 채 기도하며 무릎 꿇고 있으며, 그를 후원하는 성 스티븐이 곁에 서서 그를 인도합니다. 성인은 파란색과 금색 제의를 걸치고 있으며, 그의 순교를 상징하는 뾰족한 돌이 얹힌 책을 들고 있습니다. 두 사람은 흰 대리석 홀에 서 있으며, 벽을 따라 봉헌자의 이름이 새겨져 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_SAINT_FRANCIS"] =
    "엄격한 수도자의 신앙을 담은 스페인 바로크 유화입니다. 성 프란시스가 모래색의 후드 달린 소박한 수도복을 입고 홀로 서 있으며, 그의 얼굴은 절반이 두건의 깊은 그림자에 잠겨 있고, 두 눈은 기도하며 아래를 향하고 있습니다. 그는 죽음을 일깨우는 표상으로 사람의 두개골을 두 손에 받쳐 들고 있으며, 거의 검은 배경을 향해 단 하나의 강한 빛이 그를 비추고 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_HATAORI"] =
    "일하는 직조공을 그린 일본 우키요에 목판화입니다. 무늬가 있는 쪽빛 기모노를 입은 젊은 여인이 맨발로 커다란 목재 수직기 앞에 앉아, 한 손에 북을 쥔 채 일하던 손을 멈추고 위를 올려다보고 있으며, 빨강, 파랑, 흰색의 실들이 베틀 길이만큼 팽팽히 당겨져 있습니다. 색조는 부드러운 크림색과 차분한 파란색이며, 종이 왼쪽 위에는 붓으로 쓴 시 한 줄이 세로로 채워져 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_JANE_GREY"] =
    "극적이고 비통한 프랑스 아카데미 역사화입니다. 십 대의 여왕이 눈을 가린 채 어두운 석조 처형실에서 빛나는 흰 새틴 드레스를 입고 무릎 꿇은 채 손을 더듬어 처형대를 찾고 있으며, 나이 든 관리가 그녀의 손을 부드럽게 처형대로 인도하고 있습니다. 그녀의 뒤로는 시녀들이 기둥에 기대어 슬픔에 무너져 있고, 오른쪽에는 처형인이 도끼에 기댄 채 시선을 돌리고 기다리고 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_WANDERER"] =
    "자연 앞에 홀로 선 인간을 담은, 독일 낭만주의 유화의 대표적인 이미지입니다. 짙은 녹색 코트를 입은 젊은 남자가 보는 이에게 등을 돌린 채 바위 정상에 서서 지팡이에 기대어 있으며, 머리카락은 바람에 흩날립니다. 그의 아래로는 흰 안개의 바다가 골짜기를 삼키고 있으며, 능선과 바위 봉우리만이 섬처럼 솟아 있고, 창백한 산들이 저 멀리 흐려져 갑니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_BABEL"] =
    "성서 속 멸망할 운명의 탑을 세밀하게 가득 채워 그린 플랑드르 르네상스 유화입니다. 아치로 이루어진 거대한 나선형 탑이 일부는 흰 돌로, 일부는 거친 붉은 벽돌로 비스듬히 기울어진 채 구름 속으로 솟아오르며, 꼭대기는 아직 거칠고 미완성인 상태입니다. 그 기단 둘레로는 배들이 정박한 항구 도시가 펼쳐져 있으며, 전경에서는 한 왕이 자신의 발치에 무릎 꿇은 석공들을 돌덩이들 사이에서 시찰하고 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_YOUNG_LADY"] =
    "작고 정적이며 묘하게 현대적인 초기 네덜란드 유화 초상화입니다. 도자기처럼 매끄러운 얼굴의 창백한 젊은 여인이 금색 테를 두른 높은 검은 벨벳 머리장식 아래로 옆눈질하며 보는 이를 바라봅니다. 그녀는 흰 모피 깃이 달린 파란 가운을 입고 금색과 검은색 띠로 된 꼭 맞는 목걸이를 둘렀으며, 흔한 어두운 공허가 아니라 수수하고 어슴푸레한 벽을 배경으로 자리하고 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_KINDRED"] =
    "화가와 시인 사이의 우정에 바치는 미국 허드슨 리버파 유화입니다. 코트를 입은 두 남자가 캐츠킬산맥의 숲이 우거진 협곡 위로 돌출한 바위 턱에 서서 이야기를 나누고 있으며, 한 사람은 붓으로 풍경을 가리키고 있습니다. 아래로는 시냇물이 바위 위로 쏟아지며, 머리 위로 드리운 나무들이 아치를 이루어 그 둘레를 감싸고, 뒤편에서는 흐릿한 봉우리들이 황금빛 속으로 녹아들고 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_BLUE_BOY"] =
    "화가의 가장 유명한 작품인 영국 그랜드 매너 양식의 유화 초상화입니다. 열두 살쯤 된 소년이 반바지와 레이스 깃이 달린, 반짝이는 파란 새틴 정장을 입고 전신으로 서 있으며, 한 손은 허리에 얹고 다른 손은 깃털 장식 모자를 옆구리에 들고 있습니다. 그는 어둡고 폭풍이 이는 갈색 풍경을 배경으로 여유로운 자신감을 띠고 보는 이를 바라보며, 그 배경이 파란 의상을 더욱 타오르게 합니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_SECOND_OF_MAY"] =
    "전쟁에 대한 예술의 가장 이르고 위대한 항거 가운데 하나인 스페인 유화입니다. 등불 빛 아래, 프랑스 처형 부대가 얼굴 없는 한 줄로 서서 마드리드 외곽의 헐벗은 언덕에 모여 있는 스페인 포로들에게 소총을 겨누고 있습니다. 중앙에는 흰 셔츠를 입은 한 남자가 이미 총살된 이들의 시신 사이에 무릎 꿇은 채 총구 앞에서 두 팔을 활짝 벌리고 있으며, 그 자세는 십자가형을 떠올리게 합니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_LAST_CART"] =
    "보불 전쟁을 다룬 프랑스 군사 유화로, 굴하지 않는 최후의 저항을 담은 유명한 이미지입니다. 한 줌의 프랑스 병사들이 부서진 마을 집을 지키며 창문에서 총을 쏘고 있으며, 부상자들은 벽에 기대어 늘어져 있고 한 장교는 그들의 마지막 탄약을 헤아리고 있습니다. 방은 처참하게 부서져 문 하나가 경첩에서 떨어져 나갔고, 천장에서 회벽이 떨어지며, 동료들이 계속 싸우고 있는 문간으로 햇빛이 쏟아져 들어옵니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_EARLY_AUTUMN"] =
    "먹과 옅은 채색으로 그린 중국 두루마리 그림으로, 시들어 가는 연못을 가까이에서 담은 자연 화폭입니다. 빨강, 초록, 파랑의 잠자리들이 말라 가는 갈대와 너덜너덜해진 연잎 위를 맴돌고, 그 아래에서는 메뚜기와 벌 한 마리, 작은 개구리들이 저마다 분주합니다. 분위기는 부드러운 쇠락으로, 이제 막 시들기 시작한 풀들 사이에서 여름의 생명이 이어지고 있으며, 양쪽 가장자리를 따라 붉은 소장인이 찍혀 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_APPRECIATING_LOTUSES"] =
    "가노파의 창시자가 중국 문인 산수화 양식으로 그린 일본의 먹과 채색 족자입니다. 로브를 입은 중국 학자가 연못 가장자리의 작은 배 위에 떠 있으며, 바위 기슭에서 비스듬히 뻗어 나온 옹이진 버드나무 아래로 떠 있는 연잎을 바라보고 있습니다. 길쭉한 족자의 대부분은 안개와 트인 수면이며, 소나무 우듬지 몇 개가 안개 속으로 흐려져 가고 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_EQUESTRIAN_PORTRAIT"] =
    "말에 탄 통치자를 그린 수 세기 동안의 본보기가 된 베네치아 르네상스 유화입니다. 신성 로마 황제가 번쩍이는 완전 무장에 붉은 깃털 투구를 쓰고 창을 든 채 어두운 숲에서 말을 몰고 나오며, 뮐베르크에서 거둔 그의 승리를 기념합니다. 그의 검은 말은 진홍색 천으로 덮여 있으며, 낮게 깔린 저녁 해가 무거운 폭풍 구름 아래로 금빛과 분홍빛을 비추며 뚫고 나옵니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_THE_ARMADA"] =
    "스페인 무적함대의 격퇴를 기념하기 위해 그린 튜더 왕조의 선전용 유화 초상화입니다. 엘리자베스 여왕은 진주와 리본으로 뒤덮인 거대한 가운을 입고 앉아 있으며, 그녀의 얼굴은 폭넓은 흰 레이스 러프로 감싸여 있고, 한 손은 손가락이 아메리카 대륙에 닿은 채 지구의 위에 소유하듯 얹혀 있습니다. 그녀의 뒤편 창문들을 통해 이야기가 두 번 펼쳐집니다. 한쪽에는 잔잔한 바다 위의 잉글랜드 함대가, 다른 쪽에는 폭풍 속에서 난파되는 스페인 함선들이 보입니다. 보석으로 장식된 왕관이 그녀 옆에 놓여 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_FRANCIS_I"] =
    "프랑스 르네상스 왕실 유화 초상화입니다. 왕이 화려한 궁정 복장으로 허리 위까지 보는 이를 향하고 있는데, 검은 줄무늬가 들어간 흰색과 금색 새틴 소매에는 칼집 장식이 나 있고, 가슴에는 금사슬이 가로지르며, 머리에는 흰 깃털이 달린 검은 모자를 쓰고 있습니다. 교활해 보이는 긴 코의 수염 난 얼굴이 왕관 문양이 박힌 진홍색 다마스크 배경 앞에서 도드라집니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_SELF_PORTRAIT"] =
    "황제 루돌프 2세의 플랑드르 궁정 화가가 그린 북방 마니에리스모 양식의 유화 자화상입니다. 화가는 어깨 너머로 보는 이를 돌아보는데, 부드러운 검은 모자 아래 곱슬머리를 한 다부진 체격의 수염 난 남자로, 회청색 더블릿 위에 흰 주름 깃을 두르고 있습니다. 단조로운 갈색 배경 앞에서 붓질은 따뜻하고 직접적이며, 비스듬히 가늠하는 듯한 그의 시선이 보는 이의 눈길을 붙듭니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_VERTUMNUS"] =
    "마니에리스모 양식의 유화로, 아르침볼도의 환상적인 합성 두상 가운데 가장 유명한 작품입니다. 황제 루돌프 2세를 로마의 계절 신으로 그린 초상화로, 얼굴과 가슴 전체가 과일, 채소, 꽃으로 짜여 있습니다. 콩깍지 눈꺼풀, 배 모양 코, 체리 입술, 밀 이삭 구레나룻, 포도 머리카락으로 이루어져 있습니다. 멀리서 보면 위엄 있는 통치자이지만, 가까이서 보면 시장 좌판으로 풀어지며, 모두 검은 배경 앞에 놓여 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_LAST_SUPPER"] =
    "익숙한 장면을 새롭게 재해석한 베네치아 르네상스 후기의 유화입니다. 만찬 식탁이 보는 이를 정면으로 마주하는 대신, 어두운 선술집 홀 안으로 가파른 대각선을 그리며 멀어지고, 그 길이의 중간쯤에서 그리스도가 빛을 발하며 사도들에게 빵을 건네고 있습니다. 하인들이 음식을 나르고 앞쪽에서는 고양이 한 마리가 바구니에 코를 들이밀고 있으며, 머리 위로는 활활 타오르는 기름 등잔이 연기 자욱한 공기를 반투명하게 소용돌이치는 천사들로 가득 채우고 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_PORTRAIT_OF_A_MAN"] =
    "초기 네덜란드 유화로, 어쩌면 화가 자신의 얼굴이며 최초의 진정한 자화상 가운데 하나일 수 있습니다. 주름지고 날카로운 눈매를 가진 중년 남자가 깊은 그림자 속에서 보는 이를 똑바로 바라보며, 감고 매듭지어 조각 같은 주름으로 빚어낸 화려한 붉은 머리쓰개를 두르고 있습니다. 묘사는 바늘 끝처럼 정밀하여 주름 하나하나와 까칠한 수염까지 잡아냈으며, 인물은 검은 배경 앞에서 짙은 모피 단의 외투를 입고 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_FRONT_OF_THE_MIRROR"] =
    "베네치아 르네상스 유화로, 노년의 벨리니가 그린 평온한 만년의 걸작입니다. 적갈색 머리카락의 벌거벗은 젊은 여자가 붉은 천 위에 앉아 작은 손거울을 든 채 차분히 머리를 매만지고 있으며, 뒤편 벽의 두 번째 둥근 거울이 그녀가 두른 문양 머리쓰개의 뒷모습을 비춥니다. 그녀 옆의 창문은 구름 낀 하늘 아래 먼 푸른 산들이 보이는 초록빛 시골 풍경으로 열려 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_ADORATION"] =
    "스크로베니 예배당에 있는 초기 이탈리아 프레스코화로, 서양 미술에 자연스러운 인간의 감정을 되살린 화가가 그린 작품입니다. 목재 차양 아래에서 마리아가 아기 그리스도를 안고 있으며, 세 동방박사 가운데 가장 나이 많은 이가 무릎을 꿇고 아기의 발에 입을 맞추고 있고, 그의 왕관은 옆으로 치워져 있습니다. 왼쪽에는 낙타들이 기다리고 있습니다. 마구간 위로는 흔히 그려지는 별 대신 혜성이 짙은 푸른 하늘을 가로지르며, 모두 조토 특유의 견고하고 단순한 인물과 맑은 색채로 표현되어 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_RUBENS_AND_ISABELLA"] =
    "플랑드르 바로크 유화로, 화가가 자신과 신부를 그린 결혼 초상화입니다. 젊은 부부가 인동덩굴 아래 가까이 붙어 앉아 있으며, 그녀의 오른손이 그의 손 위에 다정하게 얹혀 있는 것이 이 그림의 고요한 중심입니다. 그는 검은 더블릿 차림에 한쪽 다리를 꼰 채 그녀보다 높이 앉아 있고, 그녀는 보라색 치마에 금실 자수를 놓은 보디스, 폭넓은 러프, 높은 밀짚모자 차림으로 무릎을 꿇고 있으며, 두 사람 모두 평온한 만족 속에 보는 이를 바라보고 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_CHILDS_BATH"] =
    "일상의 다정함을 담은 미국 인상주의 유화로, 높은 시점과 평면적인 문양에서 일본 판화의 영향이 엿보입니다. 대담한 줄무늬 드레스를 입은 어머니가 수건에 감싼 아이를 무릎에 앉혀 안고서 대야에 담긴 물로 아이의 발을 씻기고 있습니다. 두 사람의 머리가 함께 그 일을 향해 숙여져 있으며, 그들을 둘러싼 방은 꽃무늬 벽지, 칠한 궤, 화려한 카펫, 그리고 흰 물주전자가 어우러진 문양의 조각보 같습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_THE_CARD_PLAYERS"] =
    "이 주제를 다룬 유명한 연작 가운데 하나인 후기 인상주의 유화입니다. 모자를 쓴 두 농부 남자가 작은 목재 탁자를 사이에 두고 마주 앉아 카드에 몰두해 있으며, 그 사이에 놓인 한 병의 포도주가 구도의 고요한 중심을 이룹니다. 한 사람은 파이프 담배를 피우고 있으며, 물감은 흙빛 갈색, 황토색, 차분한 보라색의 끈기 있고 묵직한 붓질로 쌓아 올려져 인물들이 조각된 듯 영구적인 느낌을 줍니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_THE_SWING"] =
    "경박하고 은밀하며 그 시대 가장 유명한 그림인 프랑스 로코코 유화입니다. 무성하게 우거진 정원에서 하늘하늘한 분홍 드레스를 입은 젊은 여자가 밧줄 그네를 높이 타며 슬리퍼 한 짝을 공중으로 차 올리고 있으며, 그녀 뒤 그림자 속에 숨은 나이 든 남자가 밧줄을 당기고 있습니다. 그녀의 젊은 연인은 아래쪽 장미 덤불에 드러누워 그녀의 치맛속을 올려다보기에 더없이 알맞은 자리에 있으며, 돌로 만든 큐피드 상이 손가락을 입술에 갖다 대고 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_GIANT_MAGNOLIAS"] =
    "무성하고 거의 열대를 연상시키는 미국 정물 유화입니다. 거대한 크림빛 흰 목련 꽃 두 송이가 짙은 파란색 벨벳 천 주름 위에 잘린 채 놓여 있으며, 윤기 나는 짙은 잎들에 둘러싸여 있고, 세 번째 꽃봉오리는 아직 닫혀 있습니다. 꽃잎은 거의 검은빛에 가까운 배경 앞에서 빛을 발하며, 밀랍처럼 관능적인 정밀함으로 그려져 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_SAINT_GEORGE_KILLING"] =
    "템페라와 금으로 그린 카탈루냐 고딕 패널화입니다. 금빛 후광을 두르고 검은 갑옷을 입은 성 게오르기우스가 앞발을 든 흰 말에서 몸을 기울여 박쥐 날개를 가진 용의 떡 벌린 입 속으로 긴 창을 내리꽂고 있으며, 그들 주변 땅에는 뼈와 해골이 어지러이 흩어져 있습니다. 분홍 가운을 입은 공주가 뒤편 바위 언덕에서 기도하고 있고, 구경꾼들이 위쪽 흰 성벽 위로 몰려 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_JACQUES_AND_BERTHE"] =
    "조각가 립치즈와 그의 아내를 그린 모더니즘 유화 이중 초상화로, 모딜리아니 특유의 한눈에 알아볼 수 있는 화풍으로 그려졌습니다. 남편은 어두운 색 정장 차림으로 서서 한 손을 앉아 있는 아내의 어깨에 얹고 있으며, 흰 레이스 깃 위로 솟은 아내의 얼굴은 볼이 발그레합니다. 두 사람 모두 화가의 상징인 길쭉한 얼굴과 긴 코, 텅 빈 아몬드형 눈을 하고 있으며, 화폭 윗부분에는 두 사람의 이름이 휘갈겨 적혀 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_DASH_FOR_TIMBER"] =
    "미국 서부를 그린 유화로, 대중의 상상 속 옛 서부를 규정한 그 질주하는 활극 장면입니다. 여덟 명의 카우보이가 온 힘을 다해 곧장 보는 이를 향해 말을 달려오고 있으며, 말발굽은 땅에서 떠 있고, 그중 두 명은 안장 위에서 몸을 비틀어 뒤를 향해 총을 쏘고 있습니다. 그들 뒤로는 흙먼지 속에서 말을 탄 아파치 무리가 추격하고 있습니다. 한 사내는 부상당한 채 동료에게 기대어 늘어져 있으며, 일행은 메마른 평원 왼쪽 가장자리의 나무들을 향해 달리고 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_GEORGE_WASHINGTON_PORTRAIT"] =
    "유화로 그린 미국의 공식 국가 초상화로, 초대 대통령직의 공식 이미지입니다. 워싱턴은 수수한 검은 벨벳 정장을 입고 전신으로 서 있으며, 한 팔은 연설하는 몸짓으로 뻗고 다른 손에는 예복용 검을 들고 있고, 곁에는 깃털 펜과 잉크 스탠드가 놓인 탁자가 있습니다. 그를 둘러싼 장식은 공화국의 위엄을 드러냅니다. 성조기 방패가 새겨진 금박 의자, 대리석 기둥, 그리고 진홍색 휘장 자락이 드리워져 있으며, 저편으로는 무지개가 폭풍 구름을 뚫고 솟아 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_ATTACK_ON_BEIJING"] =
    "전시 보도 삽화 양식으로 그린 일본의 채색 판화로, 일본어와 영어로 설명이 적혀 있습니다. 연합군 병사들이 베이징 황궁의 성벽을 습격하고 있습니다. 붉은 군복을 입은 영국 병사들이 유니언 잭을 들고 전경에서 돌격하고, 흰 군복의 일본 보병이 오른쪽에서 전진하고 있습니다. 포탄이 터지며 푸른 연병장 위로 흰 연기 덩어리가 떠 있고, 그 뒤로는 궁궐의 푸른 지붕 성문과 연기 나는 성벽이 보입니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_SUMO_WRESTLER"] =
    "일본의 우키요에 목판화로, 비번인 스타 선수를 그린 유명 인사 초상입니다. 그 거구의 사내가 무늬가 들어간 로브 위에 검은 기모노를 걸치고 허리띠에 검을 차고 전신을 곧추세우고 서 있으며, 한쪽 어깨에는 둘둘 만 겉옷을 둘러메고 체크무늬 천으로 이마를 닦고 있습니다. 그의 이름은 화면 오른쪽을 따라 굵은 붉은 서예 패널로 내려 적혀 있으며, 인물은 아무런 무늬도 없는 종이를 배경으로 평면적이고 기념비적으로 그려져 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_TIGER_IN_TROPICAL_STORM"] =
    "정글을 한 번도 본 적 없는 독학 출신의 프랑스 세관원이 그린 소박파 양식의 유화입니다. 눈을 크게 뜬 호랑이 한 마리가 바람에 휘날리는 긴 풀숲에 몸을 낮게 웅크린 채 이를 드러내고 있으며, 모든 식물을 옆으로 휘게 만드는 폭풍 한가운데 갇혀 있습니다. 정글은 초록색과 붉은색의 양식화된 잎이 빽빽하게 이루는 문양이며, 비스듬히 내리치는 은빛 빗줄기가 화폭 전체를 거즈처럼 가로질러 그려져 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_THE_HOME_GUARD"] =
    "1848년 혁명을 그린 헝가리 비더마이어 양식의 유화 초상화입니다. 수염을 기른 시민군 병사가 염색하지 않은 수수한 리넨 재킷을 입고 앉아 있으며, 장갑 낀 두 손은 곧추세운 사브르의 손잡이 위에 얹혀 있고, 소매에는 그의 대의를 알리는 빨강, 흰색, 초록의 국가 완장이 둘려 있습니다. 그는 차분한 결의에 찬 표정으로 옆쪽을 바라보고 있으며, 짙은 붉은 커튼을 배경으로 따뜻한 빛을 받고 있고, 안감이 붉은 그의 외투는 의자 위에 걸쳐져 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_CEREMONIAL_SITTING"] =
    "거대한 규모로 그린 러시아 사실주의 유화로, 제국의 통치 평의회 전원을 담은 집단 초상화입니다. 금실 장식과 붉은 띠가 묵직하게 달린 어두운 색 제복을 입은 수십 명의 노년 정치인들이 흰 기둥이 늘어선 홀의 거대한 말굽 모양 붉은 의자에 둘러앉아 있으며, 홀에는 샹들리에와 왕실 초상화가 걸려 있습니다. 예순 명이 넘는 인물 각각의 얼굴은 저마다의 개별 초상이며, 레핀 특유의 빠르고 자신감 넘치는 사실주의로 그려졌습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_RUSSIAN_TSAR"] =
    "16세기의 왕실 행렬을 재현한 러시아 역사화 유화입니다. 모피 모자를 쓰고 금 브로케이드 로브를 걸친 차르가 흰 말을 타고 눈밭을 가로질러 나아가고 있으며, 그 앞에는 선명한 붉은 군복을 입은 호위병들이 길고 굽은 도끼창을 들고 앞장서고 있습니다. 짓밟힌 눈 덮인 길 양옆에서는 군중이 무릎을 꿇고 땅에 엎드려 절하고 있으며, 옛 러시아 마을의 통나무 건물들이 창백한 겨울 하늘 아래 서 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_CRUCIFIXION_OF_SAINT_PETER"] =
    "이탈리아 바로크 양식의 유화로, 카라바조 특유의 화풍으로 잔혹하고 육체적으로 그려졌습니다. 세 명의 인부가 거꾸로 못 박힌 노년의 성 베드로가 매달린 나무 십자가를 힘겹게 들어 올리고 있으며, 한 사람은 밧줄을 당기고 다른 한 사람은 들보 아래 웅크려 있어 그들의 얼굴은 가려져 있습니다. 흰 수염의 성인은 고개를 들어 못 박힌 자기 손을 바라보고 있으며, 근육질의 늙은 몸이 칠흑 같은 어둠 속에서 단 하나의 강한 빛을 받아 환히 빛나고 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_LANDSCAPE_WITH_ANT_BEAR"] =
    "브라질에서 활동한, 유럽에서 정식으로 미술을 배운 최초의 화가가 그린 네덜란드 식민지 풍경 유화입니다. 강이 흐르는 넓고 햇빛 가득한 골짜기가 두 그루의 키 큰 야자수 사이로 드넓은 하늘 아래 펼쳐지고, 멀리 언덕 위에는 흰 집들로 이루어진 식민지 정착지가 자리하고 있습니다. 전경에서는 한 무리의 아프리카계 브라질인들이 짐을 지고 길을 걸어가고 있으며, 제목의 주둥이가 긴 큰개미핥기가 오른쪽 아래의 덤불 속을 코로 헤집고 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_DUTCH_MEN_O_WAR"] =
    "당대 최고의 선박 화가가 그린 네덜란드 황금기의 해양 유화입니다. 거대한 목조 군함들이 유리처럼 잔잔한 물 위에 닻을 내리고 있으며, 돛은 힘없이 늘어지고 선체는 바다에 거울처럼 비치며, 삭구의 모든 선이 정확하게 그려져 있습니다. 작은 노 젓는 배들이 햇빛을 받은 뭉게구름이 드넓게 펼쳐진 하늘 아래 배들 사이로 승객을 실어 나르고 있으며, 장면 전체가 황금빛 고요함에 잠겨 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_HARBOR_IN_BALAKLAVA"] =
    "크림 전쟁을 그린 채색 석판화로, 현장에서 직접 전쟁을 기록한 최초의 종군 화가 중 한 사람이 그렸습니다. 황량한 항구 기슭에서 흰 담요에 감싸인 병들고 부상당한 병사들이 노새에 실린 들것에서 내려져 기다리고 있는 노 젓는 배로 옮겨지고 있습니다. 모여 있는 사람들 뒤로 헐벗은 갈색 언덕이 솟아 있고, 비탈에는 군대의 막사와 천막이 점점이 흩어져 있으며, 색조는 절제되어 기록화다운 느낌을 줍니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_PEACEMAKERS"] =
    "남북 전쟁 막바지의 실제 군사 회의를 그린 미국 역사화 유화입니다. 링컨 대통령이 증기선 선실에 앉아 손으로 턱을 괸 채 골똘히 듣고 있고, 셔먼 장군이 논쟁 중에 손짓을 하고 있으며, 그랜트 장군과 포터 제독이 어두운 색 정장 차림의 네 인물로 이루어진 원을 마저 채우고 있습니다. 그들 뒤 선실 창문 너머로는 개어 가는 하늘 사이로 무지개가 솟아 있는데, 다가올 평화를 알리는 이 그림의 조용한 징표입니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_PORTRAIT_OF_CHITASEI"] =
    "중국 소설 수호전의 108인 영웅을 다룬 구니요시의 유명한 연작 중 하나인 일본 우키요에 목판화입니다. 학자이자 책사인 오용이 용 무늬가 들어간 흘러내리는 어두운 색 로브를 입고 서서, 별이 총총히 박힌 밤하늘 아래에서 생각에 잠긴 채 수염을 쓰다듬고 있습니다. 그의 곁에는 화려하게 장식된 받침대 위에 커다란 천구의가 놓여 있으며, 일본어 글씨가 적힌 패널들이 인물을 둘러싸고 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_PORTRAIT_OF_LOUIS"] =
    "작업 중인 조각가를 포착한 18세기 영국의 유화 초상화입니다. 루빌리아크는 부드러운 모자를 쓰고 소매를 걷어 올린 풀어 헤친 셔츠 차림으로, 조형 도구를 들어 올린 채 손을 멈추고 옆을 흘끗 바라보며 받침대 위에 놓인 셰익스피어의 점토 소상을 다듬고 있습니다. 조각가는 빈손으로 자신이 빚은 작품을 가리키고 있으며, 어두운 작업실 배경을 등지고 따뜻한 빛을 받고 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_PORTRAIT_OF_NASSER"] =
    "왕실의 화려함을 두텁게 칠해 올린 페르시아 카자르 궁정의 유화 초상화입니다. 콧수염을 기른 젊은 샤는 금 자수와 진주 줄, 보석을 박은 견장, 파란 띠로 뒤덮인 진홍색 군복을 입고 뻣뻣하게 곧추 앉아 있으며, 한 손은 보석을 박은 검 위에 올려 두고 있습니다. 그는 다이아몬드 장식을 꽂은 높은 검은 모자를 쓰고 있으며, 어둡게 윤곽을 그린 두 눈으로 정면을 응시하고 있고, 그 뒤로는 왕실의 명문이 찍힌 짙은 올리브색 배경이 펼쳐져 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_FIELD_WITH_SHEAFS"] =
    "넓고 힘찬 붓질로 그린 독일 표현주의 경향의 유화 풍경화입니다. 수확을 마친 밀밭이 전경을 가득 채우며, 비스듬히 기대어 쌓인 황금빛 곡식 다발들이 줄지어 늘어서 있고, 노란색이 두텁고 밝게 칠해져 있습니다. 짙은 녹색 나무들이 한 줄로 늘어서 밭을 가로막고 있으며, 그 위로는 바람에 흩날리는 구름이 떠 있는 연한 보랏빛 푸른 하늘이 펼쳐져 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_AT_THE_EDGE_OF_THE_BROOK"] =
    "부그로가 유명세를 떨친 유리처럼 매끄러운 완벽함으로 다듬어 낸 프랑스 아카데미풍의 유화입니다. 맨발의 농촌 아이 둘이 개울가 끝의 돌 위에 앉아 있으며, 어린 소녀는 양말을 벗고 있고 짙은 머리의 동무는 물에 들어가려 치마를 걷어 올리고 있습니다. 둘은 이야기를 나누다 말고 서로 눈길을 주고받고 있으며, 그들의 피부와 헝클어진 머리카락은 부드러운 시골 풍경을 배경으로 사진처럼 매끄럽게 그려져 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_THE_KISS_ALT"] =
    "이탈리아 미술에서 가장 유명한 입맞춤이자 통일의 숨은 애국적 상징을 담은 이탈리아 낭만주의 유화입니다. 중세풍의 돌 복도에서, 깃털 장식 모자를 쓰고 갈색 망토를 두른 젊은 남자가 한 여자를 뒤로 젖혀 안으며 격정적으로 입을 맞추고 있으며, 한쪽 발은 이미 계단에 올려 도망치다 잠시 멈춘 듯한 모습입니다. 그녀의 연한 파란색 새틴 드레스가 화면 안으로 빛을 쏟아 내고 있으며, 그 너머 아치 통로로는 어두운 형체 하나가 다가오고 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_MOVING_HOUSE"] =
    "고요한 도시의 가난을 담은 러시아 리얼리즘 유화입니다. 한 노부부가 가진 모든 것을 천 보따리에 싸 들고 얼어붙은 상트페테르부르크의 강 얼음 위를 힘겹게 가로지르고 있으며, 남자는 지팡이에 의지하고 두 사람 모두 추위를 막으려 낡은 외투와 머릿수건을 두르고 있습니다. 작은 개 한 마리가 그들 앞에서 종종걸음으로 나아가고 있으며, 그 뒤로는 겨울 안개 사이로 페트로파블롭스크 요새의 금빛 첨탑이 솟아 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_MEXICAN_EXPEDITION"] =
    "보도화처럼 그려져 움직임으로 가득 찬 프랑스 해군 전쟁사 유화입니다. 삼색기를 단 프랑스 군함 한 척이 왼쪽 전경을 압도하고 있으며, 갑판 위의 장교들이 멕시코의 산후안데울루아 요새를 향한 포격을 지휘하고 물 위로는 연기가 피어오르고 있습니다. 포탄들이 배 사이로 병사들을 실어 나르는 작은 보트 가까이에 물기둥을 일으키고 있으며, 안개 낀 지평선에는 눈 덮인 화산 하나가 솟아 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_LAST_DAY_OF_POMPEII"] =
    "당대의 재난 서사시라 할 만한 거대한 화폭에 그린 러시아 낭만주의 유화입니다. 베수비오 화산이 폭발하며 폼페이 위의 하늘이 붉고 검게 타오르고, 지붕 위에서 조각상들이 무너져 내리며, 번개가 화산재 구름을 가르고 있습니다. 로마식 복장을 한 마을 사람들의 무리가 떨어지는 잔해 사이로 달아나며 망토로 아이들과 노인들을 감싸 지키고 있고, 화면 중앙에는 뒤집힌 전차 옆에 쓰러진 여인이 큰대자로 누워 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_GWDESC_GREAT_WORK_THE_ACCOLADE"] =
    "기사도를 동화처럼 그려 낸 영국 라파엘 전파풍의 유화입니다. 금발의 왕비가 흘러내리는 흰 가운을 입고 무릎 꿇은 기사의 어깨에 검을 대어, 작은 궁정 사람들 앞에서 그에게 기사 작위를 수여하고 있습니다. 그는 사슬 갑옷과 붉은 겉옷 차림으로 고개를 숙이고 있으며, 투구는 그의 옆 바닥에 놓여 있고, 돌로 된 홀과 붉은 단상은 은은히 빛나는 낭만적인 세부로 그려져 있습니다."
